function pi_check($label,$fn){global $tests,$failures;$tests++;try{$fn();echo 'PASS I '.$label."\n";}catch(Throwable $e){$failures++;echo 'FAIL I '.$label.': '.$e->getMessage()."\n";}}
function pi_landing($public,$cookies){$r=wp_remote_get('http://127.0.0.1/?eipsi_study='.rawurlencode($public).'&eipsi_confirm=1',array('timeout'=>15,'redirection'=>0,'headers'=>array('Host'=>'127.0.0.1:18080','Accept'=>'application/json'),'cookies'=>$cookies));pe_assert(!is_wp_error($r),'HTTP');return array('status'=>wp_remote_retrieve_response_code($r),'data'=>json_decode(wp_remote_retrieve_body($r),true),'headers'=>wp_remote_retrieve_headers($r));}
$keys="\ndefine('EIPSI_STUDY_ENGINE_KEYRING',array('current'=>'HTTP_TEST','keys'=>array('HTTP_TEST'=>'".str_repeat('6b',32)."')));\ndefine('EIPSI_STUDY_ENGINE_ACCESS_KEYRING',array('current'=>'ACCESS_TEST','keys'=>array('ACCESS_TEST'=>'".str_repeat('61',32)."')));\n";file_put_contents($path,'<?php'.$keys.substr($original,5));usleep(3100000);
try{
 pi_check('Initial cookie handoff is transparent and following it opens access automatically',function()use(&$p,&$f,&$cap,&$human){list($p,$h,$cookies)=pf_http_enroll();$f=pf_http_frame($p,$h,$cookies);$cap=pf_http_cap($f);$scanner=pf_http($p['public'],array(),null,$cap,array(),false);pe_assert($scanner['status']===303,'GET redirect');$row=pf_db()->row(pf_db()->prepare('SELECT consumed_at FROM '.pf_db()->table('access_capabilities').' WHERE token_hash=%s',hash('sha256',$cap)));pe_assert($row['consumed_at']===null,'GET consumed');$human=pf_http($p['public'],array(),null,$cap);pe_assert($human['status']===303,'Automatic access');$open=pf_http($p['public'],$human['cookies']);pe_assert($open['data']['state']==='OPEN_ASSESSMENT','No access');});
 pi_check('Automatic access renders no confirmation or bearer and keeps private headers',function(){list($study,$entry,$cookies)=pf_http_enroll(null,array('initial_screen'=>L\InitialScreen::defaults()));$f=pf_http_frame($study,$entry,$cookies);$cap=pf_http_cap($f);$get=pf_http($study['public'],array(),null,$cap,array(),false);pe_assert(strpos($get['headers']['location'],'eipsi_cap')===false,'Bearer URL');$landing=pi_landing($study['public'],$get['cookies']);pe_assert($landing['status']===200&&$landing['data']['state']==='OPEN_ASSESSMENT','No direct access');$html=$landing['data']['html'];pe_assert(strpos($html,$cap)===false&&strpos($html,'confirm_access')===false&&strpos($html,'Confirmar acceso')===false,'Intermediate form or bearer HTML');pe_assert(strpos($landing['headers']['cache-control'],'no-store')!==false&&$landing['headers']['referrer-policy']==='no-referrer','Headers');});
 pi_check('Automatic access requires its secret cookie and mutations still enforce Origin',function()use($p,$f){$cap=pf_http_cap($f);$get=pf_http($p['public'],array(),null,$cap,array(),false);pe_assert(pi_landing($p['public'],array())['status']===403,'Missing automatic access cookie');$bad=new WP_Http_Cookie(array('name'=>L\CapabilityLanding::pendingName($p['public']),'value'=>'invalid'));pe_assert(pi_landing($p['public'],array($bad))['status']===403,'Invalid automatic access cookie');$r=pf_http($p['public'],$get['cookies'],array('action'=>'confirm_access','csrf'=>'bad'));pe_assert($r['status']===403,'Bad CSRF');$r=pf_http($p['public'],array(),array('action'=>'confirm_access','csrf'=>'bad'));pe_assert($r['status']===403,'Missing cookie');$r=pf_http($p['public'],$get['cookies'],array('action'=>'confirm_access','csrf'=>L\Identity::csrf($p['public'],$cap)),null,array('Origin'=>'https://evil.test'));pe_assert($r['status']===403,'Origin');pe_assert(pf_http($p['public'],array(),null,$cap)['status']===303,'Invalid attempts consumed');});
 pi_check('consumed capability denies new browser but matching session replay survives',function()use($p,$cap,$human){pe_assert(pf_http($p['public'],array(),null,$cap,array(),false)['status']===403,'Replay new browser');pe_assert(pf_http($p['public'],$human['cookies'],null,$cap)['status']===303,'Matching replay');});
 pi_check('Initial credential handoff does not alter participation before the automatic exchange',function()use($p,$f){foreach(array('VERIFY_PARTICIPANT','WITHDRAWAL_OPTIONS') as $purpose){$cap=pf_http_cap($f,$purpose);$before=(new P\StudyExecutionRepository(pf_db()))->find($f['access']['execution_id']);$r=pf_http($p['public'],array(),null,$cap,array(),false);pe_assert($r['status']===303,'GET');$row=pf_db()->row(pf_db()->prepare('SELECT consumed_at FROM '.pf_db()->table('access_capabilities').' WHERE token_hash=%s',hash('sha256',$cap)));pe_assert($row['consumed_at']===null,'GET consumed');pe_equal($before,(new P\StudyExecutionRepository(pf_db()))->find($f['access']['execution_id']),'GET science mutation');}});
}finally{file_put_contents($path,$original);}
